const e = $json;
const workflowName = e.workflow?.name ?? e.execution?.workflowName ?? '';
const workflowExecutionId = e.workflow?.id ?? '';
const sourceExecutionId = e.execution?.id ?? e.executionId ?? '';
const failedNode = e.execution?.lastNodeExecuted ?? e.lastNodeExecuted ?? '';
const httpStatus = e.httpCode ?? e.statusCode ?? e.response?.status ?? 0;
const errorMessage = e.message ?? e.error?.message ?? e.execution?.error?.message ?? 'Unknown error';

return {
  json: {
    error_id: `err_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`,
    workflow_name: workflowName,
    workflow_execution_id: workflowExecutionId,
    source_execution_id: sourceExecutionId,
    failed_node: failedNode,
    http_status: httpStatus,
    error_class: '',
    error_message: errorMessage,
    operation_type: '',
    idempotency_key: '',
    retryable: false,
    attempt_number: 0,
    next_retry_at: '',
    payload_snapshot: e,
    status: 'queued',
    created_at: new Date().toISOString()
  }
};

const data = $json;

// Normalize error message: remove IDs, numbers, timestamps for stable fingerprinting
function normalizeMessage(msg) {
  if (!msg) return '';
  return msg
    .replace(/[0-9a-fA-F]{8,}/g, 'ID')        // long hex/alphanumeric IDs
    .replace(/\d{4}-\d{2}-\d{2}T[\d:.]+Z?/g, 'TIMESTAMP') // ISO timestamps
    .replace(/\d+/g, 'N')                      // any remaining numbers
    .trim()
    .toLowerCase();
}

const normalizedMessage = normalizeMessage(data.error_message);

const fingerprintSource = [
  data.workflow_name || '',
  data.failed_node || '',
  data.http_status || '',
  normalizedMessage
].join('|');

// Simple deterministic hash — no external module required
let hash = 0;
for (let i = 0; i < fingerprintSource.length; i++) {
  hash = ((hash << 5) - hash) + fingerprintSource.charCodeAt(i);
  hash |= 0;
}
const error_fingerprint = `ERR-${Math.abs(hash)}`;

return {
  json: {
    ...data,
    error_fingerprint
  }
};

const data = $json;
const status = Number(data.http_status || 0);
const errorMsg = (data.error_message || '').toLowerCase();

let error_category = 'unknown';
let severity = 'medium';
let retryable = false;
let retry_reason = '';

// Network timeout detection (no HTTP status, but timeout-related message)
const isNetworkTimeout = status === 0 && /timeout|econnrefused|network|etimedout/.test(errorMsg);
// Duplicate/conflict detection
const isDuplicateConflict = /duplicate|conflict|already exists/.test(errorMsg);

if (status === 429) {
  error_category = 'rate_limit';
  severity = 'high';
  retryable = true;
  retry_reason = 'Rate limit exceeded';
}
else if ([500, 502, 503, 504].includes(status)) {
  error_category = 'server_error';
  severity = 'high';
  retryable = true;
  retry_reason = 'Temporary server-side failure';
}
else if (isNetworkTimeout) {
  error_category = 'network_timeout';
  severity = 'high';
  retryable = true;
  retry_reason = 'Network timeout - retryable only if operation is idempotent';
}
else if (isDuplicateConflict) {
  error_category = 'duplicate_conflict';
  severity = 'medium';
  retryable = false;
  retry_reason = 'Duplicate/conflict detected - search existing record instead of recreating';
}
else if (status === 400) {
  error_category = 'bad_request';
  severity = 'medium';
  retryable = false;
  retry_reason = 'Invalid request; manual correction may be required';
}
else if (status === 401 || status === 403) {
  error_category = 'authentication_or_permission';
  severity = 'critical';
  retryable = false;
  retry_reason = 'Authentication or permission problem';
}
else if (status === 404) {
  error_category = 'not_found';
  severity = 'medium';
  retryable = false;
  retry_reason = 'Requested resource was not found';
}
else if (status >= 400 && status < 500) {
  error_category = 'client_error';
  severity = 'medium';
  retryable = false;
  retry_reason = 'Client-side request error';
}
else if (/schema|validation|parse|unexpected token/.test(errorMsg)) {
  error_category = 'code_or_schema_failure';
  severity = 'medium';
  retryable = false;
  retry_reason = 'Code or schema failure - not safe to retry';
}
else {
  error_category = 'workflow_error';
  severity = 'medium';
  retryable = false;
  retry_reason = 'Unknown or non-HTTP workflow error';
}

return {
  json: {
    ...data,
    error_category,
    severity,
    retryable,
    retry_reason
  }
};

const data = $json;

const retryableByStatus = Boolean(data.retryable);

const operation = String(data.operation_type || '').toLowerCase();

const idempotencyKey = String(data.idempotency_key || '').trim();

const safeOperations = [
  'update',
  'upsert',
  'search',
  'read',
  'get',
  'lookup'
];

const operationIsSafe = safeOperations.some(op =>
  operation.includes(op)
);

const protectedOperation =
  operation.includes('create') ||
  operation.includes('send') ||
  operation.includes('assign') ||
  operation.includes('payment');

const hasIdempotencyProtection = Boolean(idempotencyKey);

let retry_safe = false;
let retry_safety_reason = '';

if (!retryableByStatus) {
  retry_safe = false;
  retry_safety_reason = 'Error classification does not allow automatic retry';
}
else if (operationIsSafe) {
  retry_safe = true;
  retry_safety_reason = 'Operation is read/update/upsert style and is safe to retry';
}
else if (protectedOperation && hasIdempotencyProtection) {
  retry_safe = true;
  retry_safety_reason = 'Operation has idempotency protection';
}
else if (protectedOperation && !hasIdempotencyProtection) {
  retry_safe = false;
  retry_safety_reason = 'Potentially duplicate side effect without idempotency protection';
}
else {
  retry_safe = false;
  retry_safety_reason = 'Operation safety could not be established';
}

return {
  json: {
    ...data,
    retry_safe,
    retry_safety_reason
  }
};

const data = $('Determine Retry Safety').first().json;
return {
  json: {
    ...data,
    alert_status: 'new_alert',
    first_seen: new Date().toISOString(),
    last_seen: new Date().toISOString(),
    alert_count: 1,
    alerted: false
    // status field yahan touch nahi kiya — 'queued' hi rahega jo pehle set hua tha
  }
};

const now = Date.now();

return $input.all().filter(item => {
  const nextRetryAt = item.json.next_retry_at;

  if (!nextRetryAt) {
    return false;
  }

  const retryTime = new Date(nextRetryAt).getTime();

  return !Number.isNaN(retryTime) && retryTime <= now;
});

const data = $input.first().json;
const workflowName = data.workflow_name || '';

const workflowMap = {
  'AI voice HVAC Call Intelligence pipline (1)': '2TyMSPVjxctntJsm',
  'Technician Dispatch Matching Engine': '4GJTeyPzuWFNVUyc'
};

const targetWorkflowId = workflowMap[workflowName] || null;
const canReplay = Boolean(targetWorkflowId);

return {
  json: {
    ...data,
    target_workflow_id: targetWorkflowId,
    can_replay: canReplay,
    replay_reason: canReplay
      ? `Mapped to workflow: ${workflowName}`
      : `No matching workflow found for: ${workflowName}`
  }
};

const matches = $input.all();
const currentData = $('Determine Retry Safety').first().json;

if (matches.length === 0 || Object.keys(matches[0].json).length === 0) {
  // Koi purana match nahi mila — naya alert bhejo
  return [{
    json: {
      ...currentData,
      is_duplicate: false,
      suppress_alert: false
    }
  }];
}

const lastAlert = matches[0].json;
const lastAlertTime = new Date(lastAlert.last_alerted_at);
const now = new Date();
const diffMinutes = (now - lastAlertTime) / (1000 * 60);

const withinWindow = !isNaN(diffMinutes) && diffMinutes < 30;

return [{
  json: {
    ...currentData,
    is_duplicate: withinWindow,
    suppress_alert: withinWindow,
    minutes_since_last_alert: isNaN(diffMinutes) ? null : Math.round(diffMinutes),
    existing_alert_count: lastAlert.alert_count || 0
  }
}];

const data = $json;
const attempt = Number(data.attempt_number || 0) + 1;
const baseMinutes = 2;
const delayMinutes = Math.min(baseMinutes * Math.pow(2, attempt - 1), 60);
const nextRetryAt = new Date(Date.now() + delayMinutes * 60 * 1000).toISOString();

return {
  json: {
    ...data,
    attempt_number: attempt,
    next_retry_at: nextRetryAt,
    delay_minutes: delayMinutes
  }
};

const allErrors = $input.all().map(item => item.json);

// 1. Total failed executions
const totalFailed = allErrors.length;

// 2. Automatically recovered executions (status = 'resolved')
const recovered = allErrors.filter(e => e.status === 'resolved').length;

// 3. Dead-letter count (status = 'dead_letter' or 'exhausted_retries')
const deadLetterCount = allErrors.filter(e => 
  e.status === 'dead_letter' || e.status === 'exhausted_retries'
).length;

// 4. Critical authentication failures (error_category = authentication_or_permission)
const criticalAuthFailures = allErrors.filter(e => 
  e.error_category === 'authentication_or_permission'
).length;

// 5. Top failing workflows (count by workflow_name)
const workflowCounts = {};
allErrors.forEach(e => {
  const name = e.workflow_name || 'Unknown';
  workflowCounts[name] = (workflowCounts[name] || 0) + 1;
});
const topFailingWorkflows = Object.entries(workflowCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([name, count]) => `${name} (${count})`)
  .join(', ');

// 6. Top failing nodes (count by failed_node)
const nodeCounts = {};
allErrors.forEach(e => {
  const node = e.failed_node || 'Unknown';
  nodeCounts[node] = (nodeCounts[node] || 0) + 1;
});
const topFailingNodes = Object.entries(nodeCounts)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 5)
  .map(([node, count]) => `${node} (${count})`)
  .join(', ');

// 7. Oldest unresolved error (status != 'resolved')
const unresolved = allErrors.filter(e => e.status !== 'resolved' && e.created_at);
let oldestUnresolved = null;
if (unresolved.length > 0) {
  oldestUnresolved = unresolved.reduce((oldest, e) => {
    return new Date(e.created_at) < new Date(oldest.created_at) ? e : oldest;
  });
}

return [{
  json: {
    report_date: new Date().toISOString().split('T')[0],
    total_failed_executions: totalFailed,
    recovered_executions: recovered,
    dead_letter_count: deadLetterCount,
    critical_auth_failures: criticalAuthFailures,
    top_failing_workflows: topFailingWorkflows || 'None',
    top_failing_nodes: topFailingNodes || 'None',
    oldest_unresolved_error_id: oldestUnresolved?.error_id || null,
    oldest_unresolved_created_at: oldestUnresolved?.created_at || null,
    generated_at: new Date().toISOString()
  }
}];

const data = $json;

const report = `
DAILY RELIABILITY DIGEST
=========================
Report Date: ${data.report_date}

FAILURE SUMMARY
----------------
Total Failed Executions: ${data.total_failed_executions}
Automatically Recovered: ${data.recovered_executions}
Dead-Letter Count: ${data.dead_letter_count}
Critical Authentication Failures: ${data.critical_auth_failures}

TOP FAILING WORKFLOWS
----------------------
${data.top_failing_workflows}

TOP FAILING NODES
------------------
${data.top_failing_nodes}

OLDEST UNRESOLVED ERROR
------------------------
Error ID: ${data.oldest_unresolved_error_id || 'None'}
Occurred At: ${data.oldest_unresolved_created_at || 'N/A'}

LINK TO RETRY & DEAD-LETTER TABLE
-----------------------------------
https://docs.google.com/spreadsheets/d/1o1XgUeKuvnvJ2qmORxW2B--UDZZ_qjFRuIH0eXvEvss/edit

Generated At: ${data.generated_at}
`;

return [{
  json: {
    ...data,
    report_text: report.trim()
  }
}];
